const compendium = await game.packs.get(FqCardEngineModule.moduleName + ".decks-pattern-fq8").getDocuments();
let cards = [];
compendium.forEach((deckOrigin) => {
  cards = cards.concat([... deckOrigin.cards]);
});
let originDeck = compendium[0];
let deck = await Cards.create({
  ...originDeck,
  name: "AllUniqueCards",
  type: "deck",
  cards: [],
  system: {...originDeck?.system, fq: {type: "DECK"}},
  ownership: {default: 0}
});
await deck.createEmbeddedDocuments("Card", [...cards], {keepId: false});
ui.notifications.info("Création d'un deck avec un seul exemplaire de chaque carte!");
